import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Judicial Aftermath: Gernot Blümel & the Laptop Mystery","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/gericht-bluemel-laptop.md","filePath":"en/recherche/gericht-bluemel-laptop.md"}'),i={name:"en/recherche/gericht-bluemel-laptop.md"};function n(h,e,l,s,p,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="judicial-aftermath-gernot-blumel-the-laptop-mystery" tabindex="-1">Judicial Aftermath: Gernot Blümel &amp; the Laptop Mystery <a class="header-anchor" href="#judicial-aftermath-gernot-blumel-the-laptop-mystery" aria-label="Permalink to &quot;Judicial Aftermath: Gernot Blümel &amp; the Laptop Mystery&quot;">​</a></h1><p><strong>From a stroll with a baby carriage to political amnesia.</strong></p><p>Gernot Blümel, the former Finance Minister and closest confidant of Sebastian Kurz, provided one of the most bizarre chapters in recent Austrian political history in 2021. His &quot;Laptop Affair&quot; is the prime example of the modern art of data avoidance in our mockumentary.</p><hr><h2 id="the-incident-february-2021" tabindex="-1">The Incident (February 2021) <a class="header-anchor" href="#the-incident-february-2021" aria-label="Permalink to &quot;The Incident (February 2021)&quot;">​</a></h2><p>In the course of investigations into the Casinos affair, the WKStA ordered a house search at Gernot Blümel&#39;s home.</p><h3 id="highlights-of-the-absurdity" tabindex="-1">Highlights of the Absurdity: <a class="header-anchor" href="#highlights-of-the-absurdity" aria-label="Permalink to &quot;Highlights of the Absurdity:&quot;">​</a></h3><ul><li><strong>The Stroll:</strong> While the officers were at the door, Blümel&#39;s partner left the house with their child and a baby carriage.</li><li><strong>The Find:</strong> A private laptop belonging to Blümel was found in the baby carriage.</li><li><strong>The Justification:</strong> Blümel stated that the laptop only ended up in the carriage so that his partner &quot;wouldn&#39;t forget it.&quot; Critics saw this as an attempt to save evidence from seizure.</li></ul><h2 id="the-memory-gaps" tabindex="-1">The &quot;Memory Gaps&quot; <a class="header-anchor" href="#the-memory-gaps" aria-label="Permalink to &quot;The &quot;Memory Gaps&quot;&quot;">​</a></h2><p>Blümel&#39;s appearance in the Ibiza Committee of Inquiry remained unforgettable, where he stated over <strong>80 times</strong> that he could not remember certain processes, emails, or appointments.</p><hr><p><em>Sources: Protocols of the Ibiza Inquiry Committee, reporting by Standard, Presse, and ZIB2.</em></p>',12)])])}const u=t(i,[["render",n]]);export{d as __pageData,u as default};
